fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Prepare a vector with capacity equal to list length
    let mut new_list = Vec::with_capacity(list.len());

    // Append elements from n (inclusive) to end
    new_list.extend_from_slice(&list[n..]);

    // Append elements from start up to n (exclusive)
    new_list.extend_from_slice(&list[..n]);

    new_list
}